CREATE TABLE crawler_runs (id VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, source VARCHAR(32) CHARACTER SET ascii NOT NULL, started_at DATETIME(6) NOT NULL, created_by BIGINT UNSIGNED NOT NULL, created_at DATETIME(6) NOT NULL, FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE crawler_deliveries (run_id VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, batch_id VARCHAR(150) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, kind VARCHAR(12) CHARACTER SET ascii NOT NULL, payload_hash CHAR(64) CHARACTER SET ascii NOT NULL, payload LONGTEXT NOT NULL, ack TEXT NOT NULL, created_at DATETIME(6) NOT NULL, PRIMARY KEY(run_id,batch_id,kind), FOREIGN KEY(run_id) REFERENCES crawler_runs(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE processes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, source VARCHAR(32) CHARACTER SET ascii NOT NULL, external_id VARCHAR(512) COLLATE utf8mb4_bin NOT NULL, source_url VARCHAR(2048) NOT NULL, entity VARCHAR(1000) NOT NULL, reference VARCHAR(500) NOT NULL, description MEDIUMTEXT NOT NULL, deadline VARCHAR(120) NOT NULL, closing_at DATETIME(6) NULL, normalized_data MEDIUMTEXT NOT NULL, field_clocks TEXT NOT NULL, content_hash CHAR(64) CHARACTER SET ascii NOT NULL, created_by BIGINT UNSIGNED NOT NULL, team_id BIGINT UNSIGNED NULL, is_source_active BOOLEAN NOT NULL DEFAULT TRUE, first_seen_at DATETIME(6) NOT NULL, last_seen_at DATETIME(6) NOT NULL, version BIGINT UNSIGNED NOT NULL, FOREIGN KEY(created_by) REFERENCES users(id), FOREIGN KEY(team_id) REFERENCES teams(id), UNIQUE(source,external_id), INDEX process_owner(created_by,id), INDEX process_team(team_id,id), INDEX process_deadline(closing_at,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE process_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, process_id BIGINT UNSIGNED NOT NULL, crawler_run_id VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, version BIGINT UNSIGNED NOT NULL, content_hash CHAR(64) CHARACTER SET ascii NOT NULL, normalized_data MEDIUMTEXT NOT NULL, changes TEXT NOT NULL, observed_at DATETIME(6) NOT NULL, created_at DATETIME(6) NOT NULL, FOREIGN KEY(process_id) REFERENCES processes(id), FOREIGN KEY(crawler_run_id) REFERENCES crawler_runs(id), UNIQUE(process_id,version)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE process_observations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, process_id BIGINT UNSIGNED NOT NULL, run_id VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, batch_id VARCHAR(150) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, position INT UNSIGNED NOT NULL, observed_at DATETIME(6) NOT NULL, raw_data MEDIUMTEXT NOT NULL, FOREIGN KEY(process_id) REFERENCES processes(id), FOREIGN KEY(run_id) REFERENCES crawler_runs(id), UNIQUE(run_id,batch_id,position)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE process_user_marks (process_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, is_interesting BOOLEAN NOT NULL DEFAULT FALSE, note TEXT NOT NULL, version BIGINT UNSIGNED NOT NULL DEFAULT 1, updated_at DATETIME(6) NOT NULL, PRIMARY KEY(process_id,user_id), FOREIGN KEY(process_id) REFERENCES processes(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO permissions(name) VALUES ('procesos.view'),('procesos.mark'),('procesos.note'),('procesos.export'),('procesos.admin'),('crawler.runs.create'),('crawler.processes.import'),('crawler.runs.complete');
